--
-- Table structure for table `teacher_assignments`
--

DROP TABLE IF EXISTS `teacher_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teacher_assignments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `teacher_import_batch_id` bigint unsigned NOT NULL,
  `school_id` bigint unsigned DEFAULT NULL,
  `source_sheet` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_row` int unsigned NOT NULL,
  `source_npsn` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `school_resolution_status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deduplication_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_duplicate_candidate` tinyint(1) NOT NULL DEFAULT '0',
  `full_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nik` text COLLATE utf8mb4_unicode_ci,
  `nip` text COLLATE utf8mb4_unicode_ci,
  `nuptk` text COLLATE utf8mb4_unicode_ci,
  `phone` text COLLATE utf8mb4_unicode_ci,
  `birth_place` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `employment_status_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employment_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ptk_type_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ptk_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ptk_position_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ptk_position` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `education_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `education` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_payload` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `teacher_assignment_source_unique` (`teacher_import_batch_id`,`source_fingerprint`),
  KEY `teacher_assignments_school_id_foreign` (`school_id`),
  KEY `teacher_assignments_source_npsn_index` (`source_npsn`),
  KEY `teacher_assignments_school_resolution_status_index` (`school_resolution_status`),
  KEY `teacher_assignments_deduplication_fingerprint_index` (`deduplication_fingerprint`),
  KEY `teacher_assignments_is_duplicate_candidate_index` (`is_duplicate_candidate`),
  KEY `teacher_assignments_employment_status_index` (`employment_status`),
  CONSTRAINT `teacher_assignments_school_id_foreign` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE SET NULL,
  CONSTRAINT `teacher_assignments_teacher_import_batch_id_foreign` FOREIGN KEY (`teacher_import_batch_id`) REFERENCES `teacher_import_batches` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1458 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

